/* AI Evaluation dashboard. Renders window.AI_EVAL_REPORT (generated by `python -m evals.gate --site-snapshot`).
 * All text is inserted with textContent, never innerHTML. */
(function () {
  "use strict";
  var R = window.AI_EVAL_REPORT;
  if (!R) { return; }

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) { n.className = cls; }
    if (text !== undefined) { n.textContent = text; }
    return n;
  }
  function clear(id) { var n = document.getElementById(id); n.textContent = ""; return n; }
  function pct(v) { return (Math.round(v * 10000) / 100) + "%"; }

  function renderVerdict() {
    var box = clear("ai-eval-verdict");
    var total = 0, passed = 0;
    R.checks.forEach(function (c) { if (c.key === "regression") { total = c.detail.cases_total; passed = c.detail.cases_passed; } });
    var open = R.known_gaps.filter(function (g) { return g.open; }).length;
    box.appendChild(el("span", "badge " + (R.release_allowed ? "badge-green" : "badge-amber"), R.verdict));
    box.appendChild(el("p", "", total + " golden cases, " + R.agents.length + " agents, " + R.checks.length +
      " gate checks. " + passed + " scored cases pass. " + open + " tracked gaps (non-blocking)."));
  }

  function renderGate() {
    var box = clear("ai-eval-gate");
    var table = el("table", "data-table");
    var head = el("tr");
    ["Check", "Result", "Summary"].forEach(function (h) { head.appendChild(el("th", "", h)); });
    table.appendChild(head);
    R.checks.forEach(function (c) {
      var row = el("tr");
      row.appendChild(el("td", "", c.label));
      var cell = el("td");
      cell.appendChild(el("span", "badge " + (c.passed ? "badge-green" : "badge-amber"), c.passed ? "Pass" : "Fail"));
      row.appendChild(cell);
      row.appendChild(el("td", "", c.summary));
      table.appendChild(row);
    });
    box.appendChild(table);
    box.appendChild(el("p", "section-sub", "Release only if safety and quality thresholds are met. Wired into CI as .github/workflows/ai-release-gate.yml."));
  }

  function renderMetrics(agentKey) {
    var box = clear("ai-eval-metrics");
    var agent = R.agents.filter(function (a) { return a.agent === agentKey; })[0];
    box.appendChild(el("p", "", agent.cases + " cases, " + agent.failed + " failing, " + agent.tracked_gaps + " tracked-gap cases."));
    var table = el("table", "data-table");
    var head = el("tr");
    ["Metric", "Value", "Gate", "Target", "What it measures"].forEach(function (h) { head.appendChild(el("th", "", h)); });
    table.appendChild(head);
    Object.keys(agent.metrics).forEach(function (name) {
      var m = agent.metrics[name];
      var row = el("tr");
      row.appendChild(el("td", "", name));
      var v = el("td", "", String(m.value));
      if (m.status !== "pass") { v.className = "metric-fail"; }
      row.appendChild(v);
      row.appendChild(el("td", "", m.min !== null ? ">= " + m.min : "<= " + m.max));
      row.appendChild(el("td", "", String(m.target) + (m.at_target ? "" : " (not yet)")));
      row.appendChild(el("td", "", m.description));
      table.appendChild(row);
    });
    box.appendChild(table);
  }

  function renderTabs() {
    var tabs = clear("ai-eval-agent-tabs");
    R.agents.forEach(function (a, i) {
      var b = el("button", "tab-btn" + (i === 0 ? " active" : ""), a.label);
      b.type = "button";
      b.addEventListener("click", function () {
        Array.prototype.forEach.call(tabs.children, function (x) { x.classList.remove("active"); });
        b.classList.add("active");
        renderMetrics(a.agent);
      });
      tabs.appendChild(b);
    });
    renderMetrics(R.agents[0].agent);
  }

  function renderCategories() {
    var box = clear("ai-eval-categories");
    var reg = R.checks.filter(function (c) { return c.key === "regression"; })[0];
    var cats = reg.detail.cases_by_category;
    Object.keys(cats).forEach(function (k) {
      box.appendChild(el("span", "chip", k.replace(/_/g, " ") + ": " + cats[k]));
    });
  }

  function renderGaps() {
    var box = clear("ai-eval-gaps");
    var order = { critical: 0, high: 1, medium: 2, low: 3 };
    var gaps = R.known_gaps.filter(function (g) { return g.open; }).sort(function (a, b) {
      return order[a.severity] - order[b.severity] || (a.id < b.id ? -1 : 1);
    });
    var table = el("table", "data-table");
    var head = el("tr");
    ["Id", "Severity", "Agent", "Finding", "Recommended fix"].forEach(function (h) { head.appendChild(el("th", "", h)); });
    table.appendChild(head);
    gaps.forEach(function (g) {
      var row = el("tr");
      row.appendChild(el("td", "", g.id));
      var sev = el("td"); sev.appendChild(el("span", "badge " + (g.severity === "critical" ? "badge-amber" : "badge-blue"), g.severity));
      row.appendChild(sev);
      row.appendChild(el("td", "", g.agent));
      row.appendChild(el("td", "", g.title + ". " + g.description));
      row.appendChild(el("td", "", g.recommended_fix));
      table.appendChild(row);
    });
    box.appendChild(table);
  }

  renderVerdict(); renderGate(); renderTabs(); renderCategories(); renderGaps();
})();
